FILES['src/pegasus/datasus/cnes_normalize.py'] = '\nfrom __future__ import annotations\n\nimport hashlib\nimport json\nimport re\nfrom pathlib import Path\nfrom typing import Any\n\nimport polars as pl\n\nfrom pegasus.datasus.decoders import clamp_bool, filter_cnpj\nfrom pegasus.geo.municipality_crosswalk import datasus_cod6_to_ibge_cod7\n\nCAPACITY_PREFIXES = ("QTINST", "QTLEIT")\nFLAG_PREFIXES = ("GESPRG", "SERAP")\nFLAG_NAMES = {"NIVATE_A", "NIVATE_H", "ATENDAMB", "ATENDHOS", "URGEMERG", "CENTRCIR", "CENTROBS", "LEITHOSP"}\n\n\ndef _clean(value: Any) -> str | None:\n    if value is None:\n        return None\n    text = str(value).strip()\n    if not text or text.upper() in {"NA", "NAN", "NULL", "NONE"}:\n        return None\n    return text\n\n\ndef _digits(value: Any) -> str | None:\n    text = _clean(value)\n    if text is None:\n        return None\n    digits = re.sub(r"\\D", "", text)\n    return digits or None\n\n\ndef _stable_hash(value: Any) -> str:\n    payload = json.dumps(value, sort_keys=True, ensure_ascii=False, separators=(",", ":"), default=str)\n    return hashlib.sha256(payload.encode("utf-8")).hexdigest()\n\n\ndef _read_table(path: str | Path) -> pl.DataFrame:\n    path = Path(path)\n    if path.suffix.lower() == ".parquet":\n        return pl.read_parquet(path)\n    if path.suffix.lower() in {".csv", ".txt"}:\n        return pl.read_csv(path, infer_schema_length=0, ignore_errors=False)\n    raise ValueError(f"Unsupported CNES-ST input format: {path}")\n\n\ndef _period(value: Any) -> tuple[int | None, int | None, str]:\n    digits = _digits(value)\n    if digits is None:\n        return None, None, "missing"\n    if len(digits) >= 6:\n        year = int(digits[:4])\n        month = int(digits[4:6])\n        if 1 <= month <= 12:\n            return year, month, "valid"\n    if len(digits) == 4:\n        return int(digits), None, "year_only"\n    return None, None, "invalid"\n\n\ndef _mun(value: Any) -> tuple[str | None, str | None, str]:\n    digits = _digits(value)\n    if digits is None:\n        return None, None, "missing"\n    if len(digits) == 6:\n        try:\n            return digits, datasus_cod6_to_ibge_cod7(digits, strict=True), "datasus_cod6"\n        except Exception:\n            return digits, None, "unmapped_datasus_cod6"\n    if len(digits) == 7:\n        return digits[:6], digits, "ibge_cod7"\n    return None, None, "invalid"\n\n\ndef _int_nonnegative(value: Any) -> tuple[int | None, str]:\n    raw = _clean(value)\n    if raw is None:\n        return None, "missing"\n    digits = _digits(raw)\n    if digits is None:\n        return None, "invalid"\n    parsed = int(digits)\n    return (parsed, "valid") if parsed >= 0 else (None, "invalid")\n\n\ndef _capacity_columns(columns: list[str]) -> list[str]:\n    return sorted(c for c in columns if c.upper().startswith(CAPACITY_PREFIXES))\n\n\ndef _flag_columns(columns: list[str]) -> list[str]:\n    return sorted(c for c in columns if c.upper() in FLAG_NAMES or c.upper().startswith(FLAG_PREFIXES))\n\n\ndef normalize_cnes_st_record(row: dict[str, Any], *, source_manifest_hash: str) -> dict[str, Any]:\n    raw_payload = {str(k): v for k, v in row.items()}\n    year, month, period_state = _period(row.get("COMPETEN") or row.get("ANO_CMPT") or row.get("year"))\n    cod6, cod7, mun_state = _mun(row.get("CODMUN") or row.get("MUNIC_RES") or row.get("facility_municipality"))\n    facility = _clean(row.get("CNES") or row.get("facility_id"))\n    cnpj = filter_cnpj(row.get("CPF_CNPJ") or row.get("facility_cnpj"))\n    cnpj_man = filter_cnpj(row.get("CNPJ_MAN") or row.get("maintainer_cnpj"))\n    capacity_values: dict[str, int | None] = {}\n    capacity_states: dict[str, str] = {}\n    for col in _capacity_columns(list(row)):\n        value, state = _int_nonnegative(row.get(col))\n        capacity_values[col.upper()] = value\n        capacity_states[col.upper()] = state\n    flag_values: dict[str, int | None] = {}\n    flag_states: dict[str, str] = {}\n    for col in _flag_columns(list(row)):\n        decoded = clamp_bool(row.get(col))\n        flag_values[col.upper()] = decoded.value\n        flag_states[col.upper()] = decoded.state\n    invalid_flags = sum(1 for state in flag_states.values() if state in {"InvalidFlagState", "UnparseableFlag"})\n    identity_state = "valid" if facility is not None and year is not None and cod6 is not None else "invalid_identity"\n    return {\n        "facility_id": facility,\n        "source_system": "CNES-ST",\n        "year": year,\n        "month": month,\n        "period_state": period_state,\n        "mun_facility_cod6": cod6,\n        "mun_facility_cod7": cod7,\n        "municipality_code_state": mun_state,\n        "facility_cnpj": cnpj.cnpj,\n        "facility_cnpj_state": cnpj.state,\n        "maintainer_cnpj": cnpj_man.cnpj,\n        "maintainer_cnpj_state": cnpj_man.state,\n        "capacity_vector_json": json.dumps(capacity_values, ensure_ascii=False, sort_keys=True),\n        "capacity_state_json": json.dumps(capacity_states, ensure_ascii=False, sort_keys=True),\n        "capacity_total_observed": sum(v for v in capacity_values.values() if isinstance(v, int)),\n        "flag_vector_json": json.dumps(flag_values, ensure_ascii=False, sort_keys=True),\n        "flag_state_json": json.dumps(flag_states, ensure_ascii=False, sort_keys=True),\n        "invalid_flag_count": invalid_flags,\n        "flag_count": len(flag_states),\n        "record_state": identity_state,\n        "source_manifest_hash": source_manifest_hash,\n        "row_hash": _stable_hash(raw_payload),\n        "raw_json": json.dumps(raw_payload, ensure_ascii=False, sort_keys=True, default=str),\n    }\n\n\ndef normalize_cnes_st_events(*, input_path: str | Path, output_path: str | Path, source_manifest_hash: str) -> dict[str, Any]:\n    rows = [normalize_cnes_st_record(row, source_manifest_hash=source_manifest_hash) for row in _read_table(input_path).to_dicts()]\n    out = Path(output_path)\n    out.parent.mkdir(parents=True, exist_ok=True)\n    pl.DataFrame(rows).write_parquet(out)\n    return {\n        "row_count": len(rows),\n        "output_path": str(out),\n        "valid_rows": sum(1 for r in rows if r["record_state"] == "valid"),\n        "zero_facility_cnpj_rows": sum(1 for r in rows if r["facility_cnpj_state"] == "NullifiedZeroCNPJ"),\n        "invalid_flag_rows": sum(1 for r in rows if r["invalid_flag_count"] > 0),\n        "capacity_components": sorted({k for r in rows for k in json.loads(r["capacity_vector_json"]).keys()}),\n    }\n'
FILES['src/pegasus/datasus/sih_normalize.py'] = '\nfrom __future__ import annotations\n\nimport hashlib\nimport json\nimport re\nfrom datetime import datetime\nfrom pathlib import Path\nfrom typing import Any\n\nimport polars as pl\n\nfrom pegasus.datasus.decoders import decode_sih_age\nfrom pegasus.datasus.icd_parser import parse_icd\nfrom pegasus.geo.municipality_crosswalk import datasus_cod6_to_ibge_cod7\n\nSECONDARY_DIAG_COLUMNS = tuple(f"DIAGSEC{i}" for i in range(1, 10))\nSECONDARY_TYPE_COLUMNS = tuple(f"TPDISEC{i}" for i in range(1, 10))\nCOST_COMPONENTS = ("VAL_SH", "VAL_SP", "VAL_UTI", "VAL_TOT")\n\n\ndef _clean(value: Any) -> str | None:\n    if value is None:\n        return None\n    text = str(value).strip()\n    if not text or text.upper() in {"NA", "NAN", "NULL", "NONE"}:\n        return None\n    return text\n\n\ndef _digits(value: Any) -> str | None:\n    text = _clean(value)\n    if text is None:\n        return None\n    digits = re.sub(r"\\D", "", text)\n    return digits or None\n\n\ndef _stable_hash(value: Any) -> str:\n    payload = json.dumps(value, sort_keys=True, ensure_ascii=False, separators=(",", ":"), default=str)\n    return hashlib.sha256(payload.encode("utf-8")).hexdigest()\n\n\ndef _read_table(path: str | Path) -> pl.DataFrame:\n    path = Path(path)\n    if path.suffix.lower() == ".parquet":\n        return pl.read_parquet(path)\n    if path.suffix.lower() in {".csv", ".txt"}:\n        return pl.read_csv(path, infer_schema_length=0, ignore_errors=False)\n    raise ValueError(f"Unsupported SIH-RD input format: {path}")\n\n\ndef _parse_date(value: Any) -> tuple[str | None, int | None, str]:\n    text = _clean(value)\n    if text is None:\n        return None, None, "missing"\n    digits = _digits(text)\n    candidates: list[str] = []\n    if digits and len(digits) == 8:\n        candidates.append(f"{digits[0:4]}-{digits[4:6]}-{digits[6:8]}")\n        candidates.append(f"{digits[4:8]}-{digits[2:4]}-{digits[0:2]}")\n    candidates.append(text)\n    for candidate in candidates:\n        try:\n            d = datetime.fromisoformat(candidate).date()\n            return d.isoformat(), d.year, "valid"\n        except Exception:\n            pass\n    return None, None, "invalid"\n\n\ndef _mun(value: Any) -> tuple[str | None, str | None, str]:\n    digits = _digits(value)\n    if digits is None:\n        return None, None, "missing"\n    if len(digits) == 6:\n        try:\n            return digits, datasus_cod6_to_ibge_cod7(digits, strict=True), "datasus_cod6"\n        except Exception:\n            return digits, None, "unmapped_datasus_cod6"\n    if len(digits) == 7:\n        return digits[:6], digits, "ibge_cod7"\n    return None, None, "invalid"\n\n\ndef _number(value: Any) -> tuple[float | None, str, str | None]:\n    raw = _clean(value)\n    if raw is None:\n        return None, "missing", None\n    try:\n        parsed = float(raw.replace(",", "."))\n    except ValueError:\n        return None, "invalid", raw\n    return (parsed, "valid", raw) if parsed >= 0 else (None, "invalid", raw)\n\n\ndef _int_nonnegative(value: Any) -> tuple[int | None, str]:\n    number, state, _ = _number(value)\n    return (int(number), state) if number is not None else (None, state)\n\n\ndef _death_flag(value: Any) -> tuple[bool | None, str]:\n    text = _clean(value)\n    if text is None:\n        return None, "missing"\n    norm = text.casefold()\n    if norm in {"1", "sim", "yes", "true", "t", "morte", "death"}:\n        return True, "valid"\n    if norm in {"0", "não", "nao", "no", "false", "f"}:\n        return False, "valid"\n    return None, "invalid"\n\n\ndef normalize_sih_rd_record(row: dict[str, Any], *, source_manifest_hash: str) -> dict[str, Any]:\n    raw_payload = {str(k): v for k, v in row.items()}\n    admission_date, admission_year, admission_state = _parse_date(row.get("DT_INTER") or row.get("DTINTERN") or row.get("admission_date"))\n    discharge_date, _, discharge_state = _parse_date(row.get("DT_SAIDA") or row.get("DTSAIDA") or row.get("discharge_date"))\n    cod6, cod7, mun_state = _mun(row.get("MUNIC_RES") or row.get("CODMUNRES") or row.get("municipality"))\n    age = decode_sih_age(row.get("COD_IDADE") or row.get("CODIDADE") or "4", row.get("IDADE") or row.get("age"))\n    principal = parse_icd(row.get("DIAG_PRINC") or row.get("principal_icd"), topology_role="sih_principal_diagnosis", source_field="DIAG_PRINC")\n    secondary_raw: dict[str, Any] = {}\n    secondary_norm: dict[str, Any] = {}\n    secondary_states: dict[str, Any] = {}\n    for col in SECONDARY_DIAG_COLUMNS:\n        if col in row:\n            parsed = parse_icd(row.get(col), topology_role="sih_secondary_diagnosis", source_field=col)\n            secondary_raw[col] = None if row.get(col) is None else str(row.get(col))\n            secondary_norm[col] = parsed.normalized\n            secondary_states[col] = parsed.parse_state\n    secondary_type = {col: _clean(row.get(col)) for col in SECONDARY_TYPE_COLUMNS if col in row}\n    stay_days, stay_state = _int_nonnegative(row.get("DIAS_PERM") or row.get("QT_DIARIAS") or row.get("stay_length_days"))\n    icu_days_month, icu_month_state = _int_nonnegative(row.get("UTI_MES_TO"))\n    icu_days_adm, icu_adm_state = _int_nonnegative(row.get("UTI_INT_TO"))\n    death, death_state = _death_flag(row.get("MORTE") or row.get("OBITO"))\n    costs: dict[str, float | None] = {}\n    cost_states: dict[str, str] = {}\n    cost_raw: dict[str, str | None] = {}\n    for col in COST_COMPONENTS:\n        value, state, raw = _number(row.get(col))\n        costs[col] = value\n        cost_states[col] = state\n        cost_raw[col] = raw\n    admission_id = _clean(row.get("AIH") or row.get("N_AIH") or row.get("admission_id")) or _stable_hash(raw_payload)[:16]\n    record_state = "valid"\n    if admission_year is None or cod6 is None or principal.parse_state in {"missing", "blank", "unparseable", "invalid"}:\n        record_state = "invalid_identity_or_principal_diagnosis"\n    return {\n        "admission_id": f"SIH-{admission_id}",\n        "source_system": "SIH-RD",\n        "admission_date": admission_date,\n        "discharge_date": discharge_date,\n        "admission_year": admission_year,\n        "admission_date_state": admission_state,\n        "discharge_date_state": discharge_state,\n        "mun_residence_cod6": cod6,\n        "mun_residence_cod7": cod7,\n        "municipality_code_state": mun_state,\n        "age_days": age.age_days,\n        "age_years": age.age_years,\n        "age_unit": age.age_unit,\n        "age_state": age.state,\n        "sex": _clean(row.get("SEXO")),\n        "race_color_billing": _clean(row.get("RACA_COR")),\n        "race_axis_type": "sih_billing_race_color",\n        "principal_icd_raw": principal.raw,\n        "principal_icd_norm": principal.normalized,\n        "principal_icd_parse_state": principal.parse_state,\n        "secondary_icd_raw_json": json.dumps(secondary_raw, ensure_ascii=False, sort_keys=True),\n        "secondary_icd_norm_json": json.dumps(secondary_norm, ensure_ascii=False, sort_keys=True),\n        "secondary_icd_parse_states_json": json.dumps(secondary_states, ensure_ascii=False, sort_keys=True),\n        "secondary_diagnosis_type_json": json.dumps(secondary_type, ensure_ascii=False, sort_keys=True),\n        "procedure_requested": _clean(row.get("PROC_SOLIC")),\n        "procedure_performed": _clean(row.get("PROC_REA")),\n        "stay_length_days": stay_days,\n        "stay_length_state": stay_state,\n        "icu_type_mark": _clean(row.get("MARCA_UTI")),\n        "icu_days_month_total": icu_days_month,\n        "icu_days_month_state": icu_month_state,\n        "icu_days_hospitalization_total": icu_days_adm,\n        "icu_days_hospitalization_state": icu_adm_state,\n        "death_flag": death,\n        "death_flag_state": death_state,\n        "hospital_service_cost_real": costs["VAL_SH"],\n        "professional_service_cost_real": costs["VAL_SP"],\n        "icu_cost_real": costs["VAL_UTI"],\n        "total_admission_cost_real": costs["VAL_TOT"],\n        "cost_state_json": json.dumps(cost_states, ensure_ascii=False, sort_keys=True),\n        "cost_raw_json": json.dumps(cost_raw, ensure_ascii=False, sort_keys=True),\n        "record_state": record_state,\n        "source_manifest_hash": source_manifest_hash,\n        "row_hash": _stable_hash(raw_payload),\n        "raw_json": json.dumps(raw_payload, ensure_ascii=False, sort_keys=True, default=str),\n    }\n\n\ndef normalize_sih_rd_events(*, input_path: str | Path, output_path: str | Path, source_manifest_hash: str) -> dict[str, Any]:\n    rows = [normalize_sih_rd_record(row, source_manifest_hash=source_manifest_hash) for row in _read_table(input_path).to_dicts()]\n    out = Path(output_path)\n    out.parent.mkdir(parents=True, exist_ok=True)\n    pl.DataFrame(rows).write_parquet(out)\n    return {\n        "row_count": len(rows),\n        "output_path": str(out),\n        "valid_rows": sum(1 for r in rows if r["record_state"] == "valid"),\n        "deaths": sum(1 for r in rows if r["death_flag"] is True),\n        "principal_diagnosis_states": sorted({r["principal_icd_parse_state"] for r in rows}),\n        "cost_components": list(COST_COMPONENTS),\n    }\n'
FILES['src/pegasus/registries/cnes_capacity.py'] = '\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom typing import Literal\n\n\nclass CNESCapacityRegistryError(ValueError):\n    """Raised when CNES capacity requests erase vector-indexed semantics."""\n\n\n@dataclass(frozen=True)\nclass CNESCapacityComponent:\n    raw_field: str\n    component_id: str\n    carrier: str\n    unit: str\n    family: Literal["bed", "room"]\n    label: str\n\n\nCAPACITY_COMPONENTS: dict[str, CNESCapacityComponent] = {\n    "QTLEITP1": CNESCapacityComponent("QTLEITP1", "clinical_bed_capacity", "FacilityCapacityVector", "facility_capacity_units_QTLEITP1", "bed", "Clinical beds"),\n    "QTLEITP2": CNESCapacityComponent("QTLEITP2", "surgical_bed_capacity", "FacilityCapacityVector", "facility_capacity_units_QTLEITP2", "bed", "Surgical beds"),\n    "QTLEITP3": CNESCapacityComponent("QTLEITP3", "obstetric_bed_capacity", "FacilityCapacityVector", "facility_capacity_units_QTLEITP3", "bed", "Obstetric beds"),\n    "QTINST01": CNESCapacityComponent("QTINST01", "consulting_room_capacity", "FacilityCapacityVector", "facility_capacity_units_QTINST01", "room", "Consulting rooms / infrastructure component 01"),\n}\n\n\ndef get_capacity_component(raw_field: str) -> CNESCapacityComponent:\n    key = raw_field.upper()\n    if key not in CAPACITY_COMPONENTS:\n        raise CNESCapacityRegistryError(f"Unknown CNES capacity vector component: {raw_field}")\n    return CAPACITY_COMPONENTS[key]\n\n\ndef require_vector_index(raw_field: str | None) -> CNESCapacityComponent:\n    if raw_field is None or raw_field.strip().lower() in {"beds", "bed", "rooms", "room", "capacity", "generic_beds"}:\n        raise CNESCapacityRegistryError("Generic CNES beds/capacity request is illegal without a capacity-vector index.")\n    return get_capacity_component(raw_field)\n\n\ndef registry_manifest() -> dict[str, object]:\n    return {"schema_version": "1.0", "registry": "cnes_capacity_vector", "components": {k: v.__dict__ for k, v in CAPACITY_COMPONENTS.items()}}\n'
FILES['src/pegasus/registries/sih_cost.py'] = '\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\n\n\nclass SIHCostRegistryError(ValueError):\n    """Raised when SIH economic estimands collapse distinct billing components."""\n\n\n@dataclass(frozen=True)\nclass SIHCostComponent:\n    raw_field: str\n    component_id: str\n    carrier: str\n    unit: str\n    label: str\n\n\nCOST_COMPONENTS: dict[str, SIHCostComponent] = {\n    "VAL_SH": SIHCostComponent("VAL_SH", "hospital_service_cost", "HospitalCosts_SH", "reais_hospital_services", "Hospital service billing component"),\n    "VAL_SP": SIHCostComponent("VAL_SP", "professional_service_cost", "HospitalCosts_SP", "reais_professional_services", "Professional service billing component"),\n    "VAL_UTI": SIHCostComponent("VAL_UTI", "icu_cost", "HospitalCosts_UTI", "reais_icu_services", "ICU billing component"),\n    "VAL_TOT": SIHCostComponent("VAL_TOT", "total_admission_cost", "HospitalCosts_TOT", "reais_total_billing", "Total admission billing burden"),\n}\n\n\ndef get_cost_component(raw_field: str) -> SIHCostComponent:\n    key = raw_field.upper()\n    if key not in COST_COMPONENTS:\n        raise SIHCostRegistryError(f"Unknown SIH cost component: {raw_field}")\n    return COST_COMPONENTS[key]\n\n\ndef require_component_specific_cost(raw_field: str | None) -> SIHCostComponent:\n    if raw_field is None or raw_field.strip().lower() in {"cost", "costs", "generic_cost", "hospital_cost", "sih_cost"}:\n        raise SIHCostRegistryError("Generic SIH cost request is illegal when component-specific semantics are required.")\n    return get_cost_component(raw_field)\n\n\ndef registry_manifest() -> dict[str, object]:\n    return {"schema_version": "1.0", "registry": "sih_cost_components", "components": {k: v.__dict__ for k, v in COST_COMPONENTS.items()}}\n'
FILES['src/pegasus/she/cnes_capacity.py'] = '\nfrom __future__ import annotations\n\nimport json\nfrom dataclasses import dataclass\nfrom pathlib import Path\nfrom typing import Any\n\nimport polars as pl\n\nfrom pegasus.registries.cnes_capacity import CAPACITY_COMPONENTS\n\n\n@dataclass(frozen=True)\nclass CNESCapacitySummary:\n    facilities_total: int\n    years: list[int]\n    municipalities_cod6: list[str]\n    municipalities_cod7: list[str]\n    capacity_sums: dict[str, int]\n    invalid_flag_count: int\n    flag_count: int\n    zero_facility_cnpj_count: int\n    nullified_maintainer_cnpj_count: int\n\n    @property\n    def invalid_flag_share(self) -> float | None:\n        return None if self.flag_count == 0 else self.invalid_flag_count / self.flag_count\n\n    @property\n    def zero_facility_cnpj_share(self) -> float | None:\n        return None if self.facilities_total == 0 else self.zero_facility_cnpj_count / self.facilities_total\n\n    def support(self) -> dict[str, Any]:\n        return {"years": self.years, "municipalities": self.municipalities_cod6, "municipalities_ibge_cod7": self.municipalities_cod7, "n_events": self.facilities_total}\n\n\ndef summarize_cnes_capacity(events_path: str | Path, *, municipality_cod6: str | None = None) -> CNESCapacitySummary:\n    df = pl.read_parquet(events_path)\n    if municipality_cod6 is not None and "mun_facility_cod6" in df.columns:\n        df = df.filter(pl.col("mun_facility_cod6") == str(municipality_cod6))\n    valid = df.filter(pl.col("record_state") == "valid") if "record_state" in df.columns else df\n    capacity_sums = {key: 0 for key in CAPACITY_COMPONENTS}\n    for row in valid.to_dicts():\n        payload = json.loads(row.get("capacity_vector_json") or "{}")\n        for key in capacity_sums:\n            value = payload.get(key)\n            if isinstance(value, int):\n                capacity_sums[key] += value\n    years = sorted(int(x) for x in valid["year"].drop_nulls().unique().to_list()) if "year" in valid.columns else []\n    cod6 = sorted(str(x) for x in valid["mun_facility_cod6"].drop_nulls().unique().to_list()) if "mun_facility_cod6" in valid.columns else []\n    cod7 = sorted(str(x) for x in valid["mun_facility_cod7"].drop_nulls().unique().to_list()) if "mun_facility_cod7" in valid.columns else []\n    return CNESCapacitySummary(\n        facilities_total=int(valid.height),\n        years=years,\n        municipalities_cod6=cod6,\n        municipalities_cod7=cod7,\n        capacity_sums=capacity_sums,\n        invalid_flag_count=int(valid["invalid_flag_count"].sum()) if "invalid_flag_count" in valid.columns else 0,\n        flag_count=int(valid["flag_count"].sum()) if "flag_count" in valid.columns else 0,\n        zero_facility_cnpj_count=int((valid["facility_cnpj_state"] == "NullifiedZeroCNPJ").sum()) if "facility_cnpj_state" in valid.columns else 0,\n        nullified_maintainer_cnpj_count=int((valid["maintainer_cnpj_state"] == "NullifiedZeroCNPJ").sum()) if "maintainer_cnpj_state" in valid.columns else 0,\n    )\n'
FILES['src/pegasus/she/sih_costs.py'] = '\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom pathlib import Path\nfrom typing import Any\n\nimport polars as pl\n\nfrom pegasus.registries.sih_cost import COST_COMPONENTS\n\n\n@dataclass(frozen=True)\nclass SIHCostSummary:\n    admissions_total: int\n    inpatient_deaths: int\n    years: list[int]\n    municipalities_cod6: list[str]\n    municipalities_cod7: list[str]\n    stay_days_total: int\n    stay_days_observed: int\n    cost_sums: dict[str, float]\n    cost_observed: dict[str, int]\n    principal_diagnosis_states: dict[str, int]\n\n    @property\n    def inpatient_fatality(self) -> float | None:\n        return None if self.admissions_total == 0 else self.inpatient_deaths / self.admissions_total\n\n    @property\n    def mean_los(self) -> float | None:\n        return None if self.stay_days_observed == 0 else self.stay_days_total / self.stay_days_observed\n\n    def mean_costs(self) -> dict[str, float | None]:\n        return {key: (None if self.cost_observed.get(key, 0) == 0 else self.cost_sums[key] / self.cost_observed[key]) for key in COST_COMPONENTS}\n\n    def support(self) -> dict[str, Any]:\n        return {"years": self.years, "municipalities": self.municipalities_cod6, "municipalities_ibge_cod7": self.municipalities_cod7, "n_events": self.admissions_total}\n\n\ndef summarize_sih_costs(events_path: str | Path, *, municipality_cod6: str | None = None) -> SIHCostSummary:\n    df = pl.read_parquet(events_path)\n    if municipality_cod6 is not None and "mun_residence_cod6" in df.columns:\n        df = df.filter(pl.col("mun_residence_cod6") == str(municipality_cod6))\n    valid = df.filter(pl.col("record_state") == "valid") if "record_state" in df.columns else df\n    cost_columns = {"VAL_SH": "hospital_service_cost_real", "VAL_SP": "professional_service_cost_real", "VAL_UTI": "icu_cost_real", "VAL_TOT": "total_admission_cost_real"}\n    cost_sums: dict[str, float] = {}\n    cost_obs: dict[str, int] = {}\n    for raw, col in cost_columns.items():\n        cost_sums[raw] = float(valid[col].drop_nulls().sum()) if col in valid.columns else 0.0\n        cost_obs[raw] = int(valid[col].drop_nulls().len()) if col in valid.columns else 0\n    diag_counts = {}\n    if "principal_icd_parse_state" in valid.columns:\n        for row in valid.group_by("principal_icd_parse_state").len().to_dicts():\n            diag_counts[str(row["principal_icd_parse_state"])] = int(row["len"])\n    years = sorted(int(x) for x in valid["admission_year"].drop_nulls().unique().to_list()) if "admission_year" in valid.columns else []\n    cod6 = sorted(str(x) for x in valid["mun_residence_cod6"].drop_nulls().unique().to_list()) if "mun_residence_cod6" in valid.columns else []\n    cod7 = sorted(str(x) for x in valid["mun_residence_cod7"].drop_nulls().unique().to_list()) if "mun_residence_cod7" in valid.columns else []\n    stay_observed = int(valid["stay_length_days"].drop_nulls().len()) if "stay_length_days" in valid.columns else 0\n    stay_total = int(valid["stay_length_days"].drop_nulls().sum()) if "stay_length_days" in valid.columns and stay_observed else 0\n    return SIHCostSummary(int(valid.height), int((valid["death_flag"] == True).sum()) if "death_flag" in valid.columns else 0, years, cod6, cod7, stay_total, stay_observed, cost_sums, cost_obs, diag_counts)\n'
FILES['src/pegasus/output/cnes_sih_efg_bundle.py'] = '\nfrom __future__ import annotations\n\nimport json\nimport platform\nimport sys\nfrom datetime import datetime, timezone\nfrom pathlib import Path\nfrom typing import Any\n\nimport pyarrow as pa\nimport pyarrow.parquet as pq\nimport polars as pl\n\nfrom pegasus.output.bundle import create_empty_output_bundle\nfrom pegasus.output.schemas import OUTPUT_BUNDLE_FILES\nfrom pegasus.registries.cnes_capacity import CAPACITY_COMPONENTS\nfrom pegasus.registries.sih_cost import COST_COMPONENTS\nfrom pegasus.she.cnes_capacity import summarize_cnes_capacity\nfrom pegasus.she.sih_costs import summarize_sih_costs\n\n\ndef _now() -> str:\n    return datetime.now(timezone.utc).isoformat()\n\n\ndef _json(value: Any) -> str:\n    return json.dumps(value, ensure_ascii=False, sort_keys=True, indent=2, default=str)\n\n\ndef _compact(value: Any) -> str:\n    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"), default=str)\n\n\ndef _write_rows_like(path: Path, rows: list[dict[str, Any]]) -> None:\n    schema = pq.read_table(path).schema\n    shaped = [{name: row.get(name) for name in schema.names} for row in rows]\n    table = pa.Table.from_pylist(shaped, schema=schema) if shaped else pa.Table.from_arrays([pa.array([], type=f.type) for f in schema], schema=schema)\n    pq.write_table(table, path)\n\n\ndef _support(years, cod6, cod7, n_events, n_denom=None, extra=None):\n    out = {"years": years, "municipalities": cod6, "municipalities_ibge_cod7": cod7, "n_events": n_events, "n_eff": n_events, "missingness": 0.0, "denom_fragility": 1.0 if n_denom is None else 0.0}\n    if n_denom is not None:\n        out["n_denom"] = n_denom\n    if extra:\n        out.update(extra)\n    return out\n\n\ndef _field(field_id, name, kind, carrier, unit, aggregation, role, source, support, axes, operator, provenance, warnings, state="fragile", dashboard_safe="warning"):\n    return {"field_id": field_id, "name": name, "kind": kind, "carrier": carrier, "unit": unit, "support_json": _compact(support), "axes_json": _compact(axes), "aggregation": aggregation, "role_json": _compact(role), "source_json": _compact(source), "operator": operator, "provenance_json": _compact(provenance), "state": state, "warnings_json": _compact(warnings), "lineage_json": _compact({"parent_ids": [], "operator": operator, "created_at": _now()}), "materialization_state": "materialized", "path": None, "dashboard_safe": dashboard_safe}\n\n\ndef _q(field, n_events, n_denom=None, warnings=None):\n    return {"field_id": field["field_id"], "n_events": n_events, "n_denom": n_denom, "n_eff": n_events, "cov_S": 1.0, "cov_T": 1.0, "missingness": 0.0, "zero_inflation": 0.0, "denom_fragility": 1.0 if n_denom is None else 0.0, "cv": None, "moran_i": None, "temporal_roughness": None, "spatial_entropy": None, "provenance_risk": 0.2, "race_axis_source": None, "race_axis_target": None, "missing_race_share": None, "emission_prior_strength": None, "race_bridge_cv": None, "sensitivity_width": None, "bridge_mode": None, "state": field["state"], "dashboard_safe": field["dashboard_safe"], "warnings_json": _compact(warnings or []), "computed_at": _now(), "q_schema_version": "1.0"}\n\n\ndef _vd(field, definition, estimand, warning):\n    return {"field_id": field["field_id"], "name": field["name"], "definition": definition, "estimand": estimand, "interpretation_warning": warning, "unit": field["unit"], "source_system": ",".join(json.loads(field["source_json"])), "carrier": field["carrier"], "role_json": field["role_json"], "state": field["state"], "dashboard_safe": field["dashboard_safe"]}\n\n\ndef _edge(edge_id, parent, child, operator, params):\n    return {"edge_id": edge_id, "parent_field_id": parent, "child_field_id": child, "operator": operator, "params_json": _compact(params), "created_at": _now()}\n\n\ndef _warning(warning_id, field_id, source, severity, code, message):\n    return {"warning_id": warning_id, "field_id": field_id, "source": source, "severity": severity, "code": code, "message": message, "inherited_from_json": "[]", "created_at": _now()}\n\n\ndef _failed(branch_id, operator, parents, stage, terms, reason, warnings):\n    return {"failed_branch_id": branch_id, "attempted_operator": operator, "parent_field_ids": _compact(parents), "failure_stage": stage, "failed_terms": _compact(terms), "reason": reason, "warnings_json": _compact(warnings), "created_at": _now()}\n\n\ndef write_cnes_sih_fixture_efg_bundle(*, cnes_events_path: str | Path, sih_events_path: str | Path, run_dir: str | Path, municipality_cod6: str | None = None) -> Path:\n    cnes_events_path = Path(cnes_events_path); sih_events_path = Path(sih_events_path); run_dir = Path(run_dir)\n    create_empty_output_bundle(run_dir)\n    cnes = summarize_cnes_capacity(cnes_events_path, municipality_cod6=municipality_cod6)\n    sih = summarize_sih_costs(sih_events_path, municipality_cod6=municipality_cod6)\n    fields=[]; q_rows=[]; vd_rows=[]; edges=[]\n    facilities = _field("cnes_facilities_all", "CNESFacilitiesAll", "extensive_measure", "Facilities", "facilities", "additive", ["facility_stock"], ["CNES-ST"], cnes.support(), {"geography_axis":"DATASUS_COD6", "facility_axis":"CNES"}, "count_facilities", ["CNES-ST", "facility_stock_state"], [])\n    fields.append(facilities); q_rows.append(_q(facilities, cnes.facilities_total)); vd_rows.append(_vd(facilities, "Valid CNES-ST facility stock records.", "facility_count", "Facility stock, not utilization."))\n    for raw, total in cnes.capacity_sums.items():\n        comp = CAPACITY_COMPONENTS[raw]\n        f = _field(f"cnes_capacity_{raw.lower()}", f"CNESCapacity_{raw}", "extensive_measure", comp.carrier, comp.unit, "additive", ["capacity_vector_component"], ["CNES-ST"], _support(cnes.years, cnes.municipalities_cod6, cnes.municipalities_cod7, total, extra={"capacity_vector_index": raw}), {"capacity_vector_index": raw, "capacity_family": comp.family}, "sum_capacity_component", ["CNES-ST", "capacity_vector_indexed"], ["generic_beds_forbidden_without_capacity_vector_index"])\n        fields.append(f); q_rows.append(_q(f, total)); vd_rows.append(_vd(f, f"CNES vector component {raw}: {comp.label}.", "capacity_vector_component_count", "Vector-indexed capacity, not generic beds.")); edges.append(_edge(f"edge_cnes_facilities_to_{raw.lower()}", facilities["field_id"], f["field_id"], "capacity_component_sum", {"capacity_vector_index": raw}))\n    invalid_flag = _field("cnes_invalid_boolean_flag_share", "CNESInvalidBooleanFlagShare", "marked_functional", "Facilities", "proportion", "statistical_functional", ["quality_observer"], ["CNES-ST"], _support(cnes.years, cnes.municipalities_cod6, cnes.municipalities_cod7, cnes.invalid_flag_count, cnes.flag_count, {"invalid_flag_share": cnes.invalid_flag_share}), {"observer_mark":"invalid_boolean_flag_share"}, "flag_state_share", ["CNES-ST", "Clamp_bool"], ["boolean_outliers_invalid_not_true"])\n    fields.append(invalid_flag); q_rows.append(_q(invalid_flag, cnes.invalid_flag_count, cnes.flag_count)); vd_rows.append(_vd(invalid_flag, "Share of CNES boolean flags decoded invalid/unparseable.", "invalid_flag_share", "Outlier booleans are not clamped to true."))\n    zero_cnpj = _field("cnes_zero_facility_cnpj_share", "CNESZeroFacilityCNPJShare", "marked_functional", "Facilities", "proportion", "statistical_functional", ["quality_observer", "facility_linkage_gate"], ["CNES-ST"], _support(cnes.years, cnes.municipalities_cod6, cnes.municipalities_cod7, cnes.zero_facility_cnpj_count, cnes.facilities_total, {"zero_facility_cnpj_share": cnes.zero_facility_cnpj_share}), {"observer_mark":"nullified_zero_cnpj"}, "cnpj_nullification_share", ["CNES-ST", "Filter_CNPJ"], ["all_zero_cnpj_nullified_before_facility_flow_linkage"])\n    fields.append(zero_cnpj); q_rows.append(_q(zero_cnpj, cnes.zero_facility_cnpj_count, cnes.facilities_total)); vd_rows.append(_vd(zero_cnpj, "Share of all-zero CNPJ-like facility identifiers nullified.", "zero_cnpj_share", "All-zero CNPJ cannot enter facility-flow linkage."))\n    admissions = _field("sih_admissions_all", "SIHHospitalAdmissionsAll", "extensive_measure", "HospitalAdmissions", "admissions", "additive", ["hospitalization_count"], ["SIH-RD"], sih.support(), {"diagnostic_topology":"SIH_principal_diagnosis_preserved"}, "count_admissions", ["SIH-RD", "hospital_admission_event"], [])\n    fields.append(admissions); q_rows.append(_q(admissions, sih.admissions_total)); vd_rows.append(_vd(admissions, "Valid SIH-RD hospitalization admissions.", "hospital_admission_count", "Billing/hospitalization records, not incident cases."))\n    deaths = _field("sih_inpatient_deaths", "SIHInpatientDeaths", "extensive_measure", "HospitalAdmissions", "deaths", "additive", ["inpatient_death_count"], ["SIH-RD"], _support(sih.years, sih.municipalities_cod6, sih.municipalities_cod7, sih.inpatient_deaths), {"event_mark":"inpatient_death"}, "count_inpatient_deaths", ["SIH-RD", "death_flag"], [])\n    fields.append(deaths); q_rows.append(_q(deaths, sih.inpatient_deaths)); vd_rows.append(_vd(deaths, "SIH admissions marked as inpatient death.", "inpatient_death_count", "Hospital outcome mark, not mortality surveillance.")); edges.append(_edge("edge_sih_admissions_to_deaths", admissions["field_id"], deaths["field_id"], "death_flag_filter", {}))\n    fatality = _field("sih_inpatient_fatality", "SIHInpatientFatality", "intensive_density", "HospitalAdmissions", "proportion", "weighted_mean", ["hospital_outcome"], ["SIH-RD"], _support(sih.years, sih.municipalities_cod6, sih.municipalities_cod7, sih.inpatient_deaths, sih.admissions_total), {"numerator":"SIH_inpatient_deaths", "denominator":"SIH_admissions"}, "ratio", ["SIH-RD", "hospital_outcome_bridge"], ["not_case_fatality_without_case_incidence_denominator"])\n    fields.append(fatality); q_rows.append(_q(fatality, sih.inpatient_deaths, sih.admissions_total)); vd_rows.append(_vd(fatality, "Inpatient deaths divided by SIH admissions.", "inpatient_fatality_proportion", "Not population mortality or disease case fatality.")); edges.append(_edge("edge_sih_deaths_to_fatality", deaths["field_id"], fatality["field_id"], "ratio_numerator", {})); edges.append(_edge("edge_sih_admissions_to_fatality", admissions["field_id"], fatality["field_id"], "ratio_denominator", {}))\n    los = _field("sih_mean_los", "SIHMeanLengthOfStay", "marked_functional", "HospitalAdmissions", "mean_duration", "weighted_mean", ["hospitalization_duration"], ["SIH-RD"], _support(sih.years, sih.municipalities_cod6, sih.municipalities_cod7, sih.stay_days_total, sih.stay_days_observed), {"duration_mark":"DIAS_PERM_or_QT_DIARIAS"}, "mean_duration", ["SIH-RD", "stay_length_days"], ["invalid_los_not_clamped_to_zero"])\n    fields.append(los); q_rows.append(_q(los, sih.stay_days_total, sih.stay_days_observed)); vd_rows.append(_vd(los, "Mean SIH length of stay.", "mean_length_of_stay", "Invalid LOS is not clamped to zero.")); edges.append(_edge("edge_sih_admissions_to_los", admissions["field_id"], los["field_id"], "mean_duration_denominator", {}))\n    for raw, comp in COST_COMPONENTS.items():\n        total = sih.cost_sums[raw]; denom = sih.cost_observed[raw]\n        f = _field(f"sih_cost_{raw.lower()}", f"SIHCost_{raw}", "marked_functional", comp.carrier, comp.unit, "additive", ["economic_burden_component"], ["SIH-RD"], _support(sih.years, sih.municipalities_cod6, sih.municipalities_cod7, total, denom, {"cost_component": raw}), {"cost_component": raw, "economic_component_id": comp.component_id}, "sum_cost_component", ["SIH-RD", "component_specific_cost"], ["sih_cost_components_not_interchangeable"])\n        fields.append(f); q_rows.append(_q(f, total, denom)); vd_rows.append(_vd(f, f"SIH cost component {raw}: {comp.label}.", "component_specific_cost_sum", "VAL_SH, VAL_SP, VAL_UTI, and VAL_TOT remain separate.")); edges.append(_edge(f"edge_sih_admissions_to_cost_{raw.lower()}", admissions["field_id"], f["field_id"], "cost_component_support", {"component": raw}))\n    warnings = [\n        _warning("slice5a_generic_beds_forbidden", "run", "CNES-ST", "abort", "generic_beds_forbidden_without_capacity_index", "Generic CNES beds/capacity is illegal without an explicit vector index."),\n        _warning("slice5a_cnpj_nullified", zero_cnpj["field_id"], "CNES-ST", "warning", "all_zero_cnpj_nullified", "All-zero facility CNPJ-like identifiers were nullified before linkage."),\n        _warning("slice5a_sih_cost_components", "run", "SIH-RD", "abort", "generic_sih_cost_forbidden", "Generic SIH cost is illegal when component-specific semantics are required."),\n        _warning("slice5a_sih_topology", admissions["field_id"], "SIH-RD", "warning", "sih_principal_secondary_diagnosis_topology_preserved", "SIH principal diagnosis, secondary diagnoses, procedures, and SIM underlying cause are distinct topologies."),\n    ]\n    failed = [\n        _failed("failed_cnes_generic_beds_without_capacity_index", "RN", [], "carrier", ["carrier"], "Generic CNES Beds carrier requested without capacity-vector index.", ["generic_beds_forbidden_without_capacity_vector_index"]),\n        _failed("failed_facility_flow_unsanitized_cnpj", "FacilityFlow", [zero_cnpj["field_id"]], "provenance", ["provenance", "quality"], "Unsanitized/all-zero CNPJ-like identifiers cannot enter facility-flow linkage.", ["all_zero_cnpj_nullified_before_facility_flow_linkage"]),\n        _failed("failed_sih_generic_cost_pooling", "EconomicBurden", [f"sih_cost_{raw.lower()}" for raw in COST_COMPONENTS], "unit", ["unit", "carrier"], "Generic SIH cost pooling rejected; components remain separate.", ["sih_cost_components_not_interchangeable"]),\n        _failed("failed_sih_diagnostic_topology_collapse", "DiagnosticProjection", [admissions["field_id"]], "axes", ["axes"], "SIH principal/secondary topology cannot be erased without explicit projection.", ["diagnostic_topology_preserved"]),\n    ]\n    _write_rows_like(run_dir / "V_fields.parquet", fields); _write_rows_like(run_dir / "Q_tensor.parquet", q_rows); _write_rows_like(run_dir / "VariableDictionary.parquet", vd_rows); _write_rows_like(run_dir / "E_DAG.parquet", edges); _write_rows_like(run_dir / "Warnings.parquet", warnings); _write_rows_like(run_dir / "FailedBranches.parquet", failed)\n    (run_dir / "Tables").mkdir(exist_ok=True)\n    pl.DataFrame([{**{"facilities_total": cnes.facilities_total, "zero_facility_cnpj_count": cnes.zero_facility_cnpj_count, "invalid_flag_count": cnes.invalid_flag_count}, **{f"capacity_{k}": v for k, v in cnes.capacity_sums.items()}}]).write_parquet(run_dir / "Tables" / "slice5a_cnes_capacity_summary.parquet")\n    pl.DataFrame([{**{"admissions_total": sih.admissions_total, "inpatient_deaths": sih.inpatient_deaths, "mean_los": sih.mean_los}, **{f"cost_{k}": v for k, v in sih.cost_sums.items()}}]).write_parquet(run_dir / "Tables" / "slice5a_sih_cost_summary.parquet")\n    user_intent = {"workflow": "slice5a_cnes_sih_fixture", "municipality_cod6": municipality_cod6, "source_systems": ["CNES-ST", "SIH-RD"]}\n    run_config = {"schema_version": "1.0", "workflow": "slice5a_cnes_sih_fixture", "source_systems": ["CNES-ST", "SIH-RD"], "source_hashes": {"cnes_events": str(cnes_events_path), "sih_events": str(sih_events_path)}, "registry_hashes": {"cnes_capacity": "fixture_v1", "sih_cost": "fixture_v1"}, "slice5a": {"generic_beds_blocked": True, "generic_sih_cost_blocked": True, "facility_flow_requires_sanitized_cnpj": True}}\n    telemetry = {"stage_status": {"datasus_normalize": "success", "she_build": "success", "efg_build": "success", "q_tensor": "success", "output_serialization": "success", "output_validation": "success", "population_solver": "blocked", "stdfm": "blocked", "pirs_model": "blocked", "pirs_hsic": "blocked"}, "stage_durations_seconds": {}, "stage_errors": {"population_solver": "No denominator tensor invoked in Slice 5A.", "stdfm": "ST-DFM not invoked in Slice 5A.", "pirs_model": "PIRS not invoked in Slice 5A.", "pirs_hsic": "HSIC not invoked in Slice 5A."}, "resource_summary": {"rows_read": {"cnes_events": cnes.facilities_total, "sih_events": sih.admissions_total}, "rows_written": {"V_fields": len(fields), "Q_tensor": len(q_rows), "VariableDictionary": len(vd_rows)}}}\n    manifest = {"schema_version": "1.0", "run_id": run_dir.name, "generated_at": _now(), "workflow": "slice5a_cnes_sih_fixture", "source_hashes": run_config["source_hashes"], "registry_hashes": run_config["registry_hashes"], "telemetry": telemetry, "environment": {"python": sys.version.split()[0], "platform": platform.platform()}}\n    p_vector = {"source_systems": ["CNES-ST", "SIH-RD"], "field_count": len(fields), "blocked_outputs": [f["failed_branch_id"] for f in failed], "provenance": {row["field_id"]: json.loads(row["provenance_json"]) for row in fields}}\n    (run_dir / "UserIntent.json").write_text(_json(user_intent), encoding="utf-8"); (run_dir / "RunConfig.json").write_text(_json(run_config), encoding="utf-8"); (run_dir / "ReproducibilityManifest.json").write_text(_json(manifest), encoding="utf-8"); (run_dir / "P_vector.json").write_text(_json(p_vector), encoding="utf-8")\n    expected = set(OUTPUT_BUNDLE_FILES.values()); found = {p.name for p in run_dir.iterdir()}\n    if found - expected or expected - found:\n        raise RuntimeError(f"Invalid first-class bundle keys. extra={sorted(found - expected)} missing={sorted(expected - found)}")\n    return run_dir\n'
