FILES['tests/unit/test_cnes_sih_normalize.py'] = '\nfrom pathlib import Path\nimport polars as pl\nfrom pegasus.datasus.cnes_normalize import normalize_cnes_st_events\nfrom pegasus.datasus.sih_normalize import normalize_sih_rd_events\n\n\ndef test_cnes_normalization_preserves_capacity_flags_and_cnpj(tmp_path: Path):\n    out = tmp_path / "cnes.parquet"\n    result = normalize_cnes_st_events(input_path="tests/fixtures/datasus/cnes_st_fixture.csv", output_path=out, source_manifest_hash="fixture")\n    df = pl.read_parquet(out)\n    assert result["row_count"] == 3\n    assert result["zero_facility_cnpj_rows"] == 1\n    assert result["invalid_flag_rows"] == 2\n    assert "QTLEITP3" in result["capacity_components"]\n    assert "capacity_vector_json" in df.columns\n    assert "flag_state_json" in df.columns\n\n\ndef test_sih_normalization_preserves_diagnostic_topology_and_cost_components(tmp_path: Path):\n    out = tmp_path / "sih.parquet"\n    result = normalize_sih_rd_events(input_path="tests/fixtures/datasus/sih_rd_fixture.csv", output_path=out, source_manifest_hash="fixture")\n    df = pl.read_parquet(out)\n    assert result["row_count"] == 3\n    assert result["deaths"] == 1\n    assert set(result["cost_components"]) == {"VAL_SH", "VAL_SP", "VAL_UTI", "VAL_TOT"}\n    assert "principal_icd_norm" in df.columns\n    assert "secondary_icd_norm_json" in df.columns\n    assert "hospital_service_cost_real" in df.columns\n    assert "professional_service_cost_real" in df.columns\n    assert "icu_cost_real" in df.columns\n    assert "total_admission_cost_real" in df.columns\n'
FILES['tests/unit/test_cnes_sih_registries.py'] = '\nimport pytest\nfrom pegasus.registries.cnes_capacity import CNESCapacityRegistryError, get_capacity_component, require_vector_index\nfrom pegasus.registries.sih_cost import SIHCostRegistryError, get_cost_component, require_component_specific_cost\n\n\ndef test_cnes_capacity_registry_blocks_generic_beds():\n    assert get_capacity_component("QTLEITP3").component_id == "obstetric_bed_capacity"\n    with pytest.raises(CNESCapacityRegistryError):\n        require_vector_index("Beds")\n\n\ndef test_sih_cost_registry_blocks_generic_cost_and_preserves_components():\n    assert get_cost_component("VAL_SH").unit == "reais_hospital_services"\n    assert get_cost_component("VAL_SP").unit == "reais_professional_services"\n    assert get_cost_component("VAL_UTI").unit == "reais_icu_services"\n    assert get_cost_component("VAL_TOT").unit == "reais_total_billing"\n    with pytest.raises(SIHCostRegistryError):\n        require_component_specific_cost("cost")\n'
FILES['tests/integration/test_slice5a_cnes_sih_integration.py'] = '\nfrom pathlib import Path\nimport polars as pl\nfrom pegasus.workflows.cnes_sih import run_build_cnes_sih_fixture, run_datasus_normalize_cnes, run_datasus_normalize_sih\n\n\ndef test_slice5a_cnes_sih_bundle_validates_and_preserves_contracts(tmp_path: Path):\n    cnes = tmp_path / "cnes.parquet"\n    sih = tmp_path / "sih.parquet"\n    run = tmp_path / "run"\n    run_datasus_normalize_cnes(input_path="tests/fixtures/datasus/cnes_st_fixture.csv", output_path=cnes, source_manifest_hash="fixture")\n    run_datasus_normalize_sih(input_path="tests/fixtures/datasus/sih_rd_fixture.csv", output_path=sih, source_manifest_hash="fixture")\n    result = run_build_cnes_sih_fixture(cnes_events_path=cnes, sih_events_path=sih, run_dir=run, municipality_cod6="270430")\n    assert result["validation"].ok, result["validation"].errors\n    names = set(pl.read_parquet(run / "V_fields.parquet")["name"].to_list())\n    for name in ["CNESCapacity_QTLEITP1", "CNESCapacity_QTLEITP2", "CNESCapacity_QTLEITP3", "CNESInvalidBooleanFlagShare", "CNESZeroFacilityCNPJShare", "SIHHospitalAdmissionsAll", "SIHInpatientFatality", "SIHCost_VAL_SH", "SIHCost_VAL_SP", "SIHCost_VAL_UTI", "SIHCost_VAL_TOT"]:\n        assert name in names\n    failed_ids = set(pl.read_parquet(run / "FailedBranches.parquet")["failed_branch_id"].to_list())\n    for branch in ["failed_cnes_generic_beds_without_capacity_index", "failed_facility_flow_unsanitized_cnpj", "failed_sih_generic_cost_pooling", "failed_sih_diagnostic_topology_collapse"]:\n        assert branch in failed_ids\n'
FILES['scripts/dev/audits/audit_slice5a_cnes_sih.py'] = '\nfrom __future__ import annotations\nimport argparse\nfrom pathlib import Path\nimport polars as pl\nfrom pegasus.output.validate import validate_output_bundle\n\n\ndef main() -> None:\n    parser = argparse.ArgumentParser()\n    parser.add_argument("--run", required=True)\n    run = Path(parser.parse_args().run)\n    result = validate_output_bundle(run_dir=str(run))\n    if not result.ok:\n        raise SystemExit("Output validation failed: " + "; ".join(result.errors))\n    v = pl.read_parquet(run / "V_fields.parquet")\n    failed = pl.read_parquet(run / "FailedBranches.parquet")\n    warnings = pl.read_parquet(run / "Warnings.parquet")\n    names = set(v["name"].to_list())\n    required = {"CNESFacilitiesAll", "CNESCapacity_QTLEITP1", "CNESCapacity_QTLEITP2", "CNESCapacity_QTLEITP3", "CNESInvalidBooleanFlagShare", "CNESZeroFacilityCNPJShare", "SIHHospitalAdmissionsAll", "SIHInpatientDeaths", "SIHInpatientFatality", "SIHMeanLengthOfStay", "SIHCost_VAL_SH", "SIHCost_VAL_SP", "SIHCost_VAL_UTI", "SIHCost_VAL_TOT"}\n    if required - names:\n        raise SystemExit(f"Missing required Slice 5A fields: {sorted(required - names)}")\n    failed_ids = set(failed["failed_branch_id"].to_list())\n    for branch in ["failed_cnes_generic_beds_without_capacity_index", "failed_facility_flow_unsanitized_cnpj", "failed_sih_generic_cost_pooling", "failed_sih_diagnostic_topology_collapse"]:\n        if branch not in failed_ids:\n            raise SystemExit(f"Missing failed branch: {branch}")\n    warning_codes = set(warnings["code"].to_list())\n    for code in ["generic_beds_forbidden_without_capacity_index", "all_zero_cnpj_nullified", "generic_sih_cost_forbidden", "sih_principal_secondary_diagnosis_topology_preserved"]:\n        if code not in warning_codes:\n            raise SystemExit(f"Missing warning code: {code}")\n    print("AUDIT PASSED: Slice 5A CNES-ST/SIH-RD source-realistic normalization, indexed CNES capacity, SIH component costs, and hard failed branches validated.")\n\n\nif __name__ == "__main__":\n    main()\n'
CLI_BLOCK = '\n\n@datasus_app.command("normalize-cnes")\ndef datasus_normalize_cnes(\n    input_path: Path = typer.Option(..., "--input"),\n    output_path: Path = typer.Option(..., "--output"),\n    source_manifest_hash: str = typer.Option("fixture", "--source-manifest-hash"),\n) -> None:\n    from pegasus.workflows.cnes_sih import run_datasus_normalize_cnes\n    result = run_datasus_normalize_cnes(input_path=input_path, output_path=output_path, source_manifest_hash=source_manifest_hash)\n    print(f"[green]cnes normalized[/green] rows={result[\'row_count\']} output={result[\'output_path\']}")\n\n\n@datasus_app.command("normalize-sih")\ndef datasus_normalize_sih(\n    input_path: Path = typer.Option(..., "--input"),\n    output_path: Path = typer.Option(..., "--output"),\n    source_manifest_hash: str = typer.Option("fixture", "--source-manifest-hash"),\n) -> None:\n    from pegasus.workflows.cnes_sih import run_datasus_normalize_sih\n    result = run_datasus_normalize_sih(input_path=input_path, output_path=output_path, source_manifest_hash=source_manifest_hash)\n    print(f"[green]sih normalized[/green] rows={result[\'row_count\']} output={result[\'output_path\']}")\n\n\n@efg_app.command("build-cnes-sih-fixture")\ndef efg_build_cnes_sih_fixture(\n    cnes_events: Path = typer.Option(..., "--cnes-events"),\n    sih_events: Path = typer.Option(..., "--sih-events"),\n    run_dir: Path = typer.Option(..., "--run-dir"),\n    municipality_cod6: str | None = typer.Option(None, "--municipality-cod6"),\n) -> None:\n    from pegasus.workflows.cnes_sih import run_build_cnes_sih_fixture\n    result = run_build_cnes_sih_fixture(cnes_events_path=cnes_events, sih_events_path=sih_events, run_dir=run_dir, municipality_cod6=municipality_cod6)\n    validation = result["validation"]\n    if not validation.ok:\n        _fail(validation.errors)\n    print(f"[green]CNES/SIH fixture EFG bundle valid[/green] {result[\'run_dir\']}")\n'

def write(path: str, content: str) -> None:
    target = ROOT / path
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content.strip() + "\n", encoding="utf-8")


def patch_cli() -> None:
    path = ROOT / "src/pegasus/cli.py"
    text = path.read_text(encoding="utf-8")
    if "normalize-cnes" in text and "build-cnes-sih-fixture" in text:
        print("CLI already has Slice 5A commands; skipping CLI append.")
        return
    if "datasus_app = typer.Typer" not in text or "efg_app = typer.Typer" not in text:
        raise RuntimeError("Cannot patch CLI: expected Typer app markers not found.")
    path.write_text(text.rstrip() + "\n" + CLI_BLOCK + "\n", encoding="utf-8")


def preflight() -> None:
    required = ["pyproject.toml", "src/pegasus/cli.py", "src/pegasus/datasus/decoders.py", "src/pegasus/datasus/icd_parser.py", "src/pegasus/output/bundle.py", "src/pegasus/output/validate.py", "src/pegasus/workflows/compile.py", "tests/fixtures/datasus/sim_do_fixture.csv"]
    missing = [p for p in required if not (ROOT / p).exists()]
    if missing:
        raise RuntimeError(f"Slice 5A preflight failed; missing required files: {missing}")
    print("Slice 5A updater preflight passed.")


def main() -> None:
    preflight()
    print("CREATE/REPLACE:")
    for rel in FILES:
        print(f"  {rel}")
    print("PATCH:\n  src/pegasus/cli.py")
    for rel, content in FILES.items():
        write(rel, content)
    patch_cli()
    print("Applied Slice 5A CNES-ST/SIH-RD source-realism foundation.")


if __name__ == "__main__":
    main()
